export function FormState({
  fieldLabel = "{{fieldLabel}}",
  fieldValue = "{{fieldValue}}",
  status = "{{status}}",
  accent = "{{accent}}",
}) {
  const borderColor = status === "invalid" ? "#E8A020" : status === "valid" ? accent : "#24143030";
  const msg = { pristine: ["Not yet edited", "#24143099"], invalid: ["Enter a valid email address", "#E8A020"], valid: ["Looks good", accent] }[status];
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <label style={{ display: "block", fontSize: 11, fontWeight: 600, marginBottom: 4 }}>{fieldLabel}</label>
      <input type="text" defaultValue={fieldValue} readOnly style={{ width: "100%", boxSizing: "border-box", padding: "9px 10px", borderRadius: 6, border: `2px solid ${borderColor}`, fontSize: 13 }} />
      <p style={{ margin: "6px 0 0", fontSize: 11, fontWeight: status === "pristine" ? 400 : 600, color: msg[1] }}>{msg[0]}</p>
    </div>
  );
}
